package com.projectdark.mobile;
import android.content.Context;import android.graphics.*;import com.projectdark.mobile.world.*;import java.util.*;import java.io.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class TempleV211Test {
 Context c;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();c.getSharedPreferences("project_dark_f5m_v1",0).edit().clear().commit();F5mSaveStore.install(c);}
 RpgProgressionState player(String job,int hp,int mp,long exp){RpgProgressionState r=new RpgProgressionState();r.restoreProgression(99,exp);assertTrue(r.restoreJobCode(job));r.restoreBaseResources(hp,mp);return r;}
 @Test public void level99RetainsRewardsUsesLongCapAndPreservesOldOvercapBalance(){RpgProgressionState r=player("WARRIOR",4000,2000,2_200_000_000L);r.grantAdaptedReward(1_000_000_000L,0);assertEquals(3_200_000_000L,r.normalExp().longValue());r.grantAdaptedReward(Long.MAX_VALUE,0);assertEquals(TempleGrowthPolicy.EXP_CAP,r.normalExp().longValue());assertEquals(99,r.normalLevel().intValue());assertEquals(1f,PostF5mHudPresentation.expRatio(r),0);r.restoreProgression(99,5_000_000_000L);r.grantAdaptedReward(20,0);assertEquals(5_000_000_000L,r.normalExp().longValue());r.restoreProgression(98,LevelExpCurve.requiredForNext(98)-20);r.grantAdaptedReward(100,0);assertEquals(99,r.normalLevel().intValue());assertEquals(80,r.normalExp().longValue());}
 @Test public void userFormulaChargesExactHpAndMpCostsAndBatchEqualsRepeatedPurchases(){
  RpgProgressionState r=player("WARRIOR",4000,4000,TempleGrowthPolicy.EXP_CAP);long start=r.normalExp();
  assertEquals(418_500_000L,TempleGrowthPolicy.quote(r,TempleGrowthPolicy.Resource.HP,120));
  for(int i=0;i<120;i++)assertEquals(TempleGrowthPolicy.Result.OK,r.buyTempleResource(TempleGrowthPolicy.Resource.HP,1));
  assertEquals(10000,r.baseMaxHp());assertEquals(418_500_000L,start-r.normalExp());
  assertEquals(2_000_000L,TempleGrowthPolicy.singleCost(4000));assertEquals(10_000_000L,TempleGrowthPolicy.singleCost(20000));
  for(TempleGrowthPolicy.Resource resource:TempleGrowthPolicy.Resource.values())for(int base:new int[]{1,4000,10000,20000})for(int count:new int[]{1,10,100,1000}){
   RpgProgressionState batch=player("WARRIOR",base,base,Long.MAX_VALUE/4),one=player("WARRIOR",base,base,Long.MAX_VALUE/4);
   long quoted=TempleGrowthPolicy.quote(batch,resource,count),paid=0;
   for(int i=0;i<count;i++){paid+=TempleGrowthPolicy.quote(one,resource,1);assertEquals(TempleGrowthPolicy.Result.OK,one.buyTempleResource(resource,1));}
   assertEquals(paid,quoted);assertEquals(TempleGrowthPolicy.Result.OK,batch.buyTempleResource(resource,count));
   assertEquals(one.normalExp(),batch.normalExp());assertEquals(one.baseMaxHp(),batch.baseMaxHp());assertEquals(one.baseMaxMp(),batch.baseMaxMp());
  }
  assertEquals(329_250_000L,TempleGrowthPolicy.quote(player("WARRIOR",4000,4000,0),TempleGrowthPolicy.Resource.MP,120));
 }
 @Test public void exactFormulaPreservesInsufficientBalancesAndUsesLongAtHighResources(){
  for(TempleGrowthPolicy.Resource resource:TempleGrowthPolicy.Resource.values()){
   RpgProgressionState r=player("WARRIOR",4000,4000,1_999_999L);
   assertEquals(2_000_000L,TempleGrowthPolicy.quote(r,resource,1));assertEquals(TempleGrowthPolicy.Result.INSUFFICIENT_EXP,r.buyTempleResource(resource,1));
   assertEquals(1_999_999L,r.normalExp().longValue());assertEquals(4000,r.baseMaxHp());assertEquals(4000,r.baseMaxMp());
   r.restoreProgression(99,2_000_000L);assertEquals(TempleGrowthPolicy.Result.OK,r.buyTempleResource(resource,1));assertEquals(0,r.normalExp().longValue());
   assertEquals(resource==TempleGrowthPolicy.Resource.HP?4050:4000,r.baseMaxHp());assertEquals(resource==TempleGrowthPolicy.Resource.MP?4025:4000,r.baseMaxMp());
   assertEquals(-1,TempleGrowthPolicy.quote(r,resource,-1));assertEquals(-1,TempleGrowthPolicy.quote(r,resource,1001));
   r.restoreBaseResources(Integer.MAX_VALUE-50,Integer.MAX_VALUE-25);
   assertEquals(1_073_741_798_500L,TempleGrowthPolicy.quote(r,TempleGrowthPolicy.Resource.HP,1));
   assertEquals(1_073_741_811_000L,TempleGrowthPolicy.quote(r,TempleGrowthPolicy.Resource.MP,1));
   assertEquals(-1,TempleGrowthPolicy.quote(r,resource,2));
  }
 }

 @Test public void fiveJobsAdvanceWithoutSkillsOrOfferingsAndCannotPayTwice(){for(String job:CampaignProgress.JOBS){RpgProgressionState r=player(job,TempleGrowthPolicy.hpRequired(job)-1,TempleGrowthPolicy.mpRequired(job),300_000_000L);assertEquals(TempleGrowthPolicy.Result.STATS_REQUIRED,r.advanceAtTemple());r.restoreBaseResources(TempleGrowthPolicy.hpRequired(job),TempleGrowthPolicy.mpRequired(job));assertEquals(TempleGrowthPolicy.Result.OK,r.advanceAtTemple());assertEquals(50_000_000L,r.normalExp().longValue());assertEquals(RpgProgressionState.ProgressionNode.FIRST_ADVANCEMENT,r.progressionNode());assertEquals(TempleGrowthPolicy.Result.ALREADY_ADVANCED,r.advanceAtTemple());assertEquals(50_000_000L,r.normalExp().longValue());}}
 @Test public void nativeRoomsHaveConnectedEntryExitAndServicePaths(){for(TownInteriorDef d:TownInteriorDef.TEMPLE){assertNotNull(d.original());assertFalse(d.navigationTiles().isEmpty());assertFalse(d.blocked(d.original().spawnU,d.original().spawnV));assertFalse(d.blocked(d.original().exitU,d.original().exitV));Set<String> seen=new HashSet<>();ArrayDeque<int[]> q=new ArrayDeque<>();q.add(new int[]{d.original().spawnU,d.original().spawnV});while(!q.isEmpty()){int[] a=q.remove();String k=a[0]+","+a[1];if(seen.contains(k)||d.blocked(a[0],a[1]))continue;seen.add(k);for(int[] v:new int[][]{{1,0},{-1,0},{0,1},{0,-1}})q.add(new int[]{a[0]+v[0],a[1]+v[1]});}assertTrue(d.mapId+" exit reachable",seen.contains(d.original().exitU+","+d.original().exitV));if(!d.mapId.endsWith("_hub"))assertTrue(d.mapId+" NPC approach reachable",seen.contains(d.customerU+","+d.customerV));}}
 void capture(GameView v,String name)throws Exception{Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));File f=new File("build/reports/horror-v179/v211/"+name+".png");f.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 @Test public void actualNpcInputPurchasesAndPromotionPersistAcrossNewRuntime()throws Exception{GameView v=new GameView(c);v.layout(0,0,960,540);v.setSkillTestMode(false);RuntimeState s=TownInteriorTest.field(v,"state");s.rpg().restoreProgression(99,1_000_000_000L);assertTrue(s.rpg().restoreJobCode("WARRIOR"));s.rpg().restoreBaseResources(17000,5000);s.applyDerivedGrowth();TownInteriorTest.enter(v,TownInteriorDef.forMap("milles_interior_temple_seo"));WorldRuntimeAdapter w=TownInteriorTest.field(v,"reagentShopAdapter");TownInteriorDef d=TownInteriorDef.forMap(s.currentMapId());WorldCameraTransform.Point npc=w.worldToScreen(d.npcX(),d.npcY());TownInteriorTest.tap(v,npc.x,npc.y-24);TownInteriorTest.tick(v,180);TempleGrowthWindow win=TownInteriorTest.field(v,"templeWindow");assertTrue(win.isOpen());capture(v,"seo-purchase");long cost=TempleGrowthPolicy.quote(s.rpg(),TempleGrowthPolicy.Resource.HP,1);TownInteriorTest.tap(v,680,435);TownInteriorTest.tap(v,680,435);assertEquals(17050,s.rpg().baseMaxHp());assertEquals(1_000_000_000L-cost,s.rpg().normalExp().longValue());TownInteriorTest.tap(v,450,165);long mpCost=TempleGrowthPolicy.quote(s.rpg(),TempleGrowthPolicy.Resource.MP,1);TownInteriorTest.tap(v,680,435);TownInteriorTest.tap(v,680,435);assertEquals(5025,s.rpg().baseMaxMp());assertEquals(1_000_000_000L-cost-mpCost,s.rpg().normalExp().longValue());capture(v,"seo-mp-purchase");TownInteriorTest.tap(v,650,165);TownInteriorTest.tap(v,680,435);capture(v,"advancement-confirm");TownInteriorTest.tap(v,680,435);assertTrue(s.rpg().firstAdvanced());assertTrue(F5mSaveStore.checkpointActive());F5mSaveStore.install(c);GameView next=new GameView(c);next.layout(0,0,960,540);RuntimeState restored=TownInteriorTest.field(next,"state");assertTrue(restored.rpg().firstAdvanced());assertEquals(s.rpg().normalExp(),restored.rpg().normalExp());assertEquals(17050,restored.rpg().baseMaxHp());assertEquals(5025,restored.rpg().baseMaxMp());assertEquals(d.mapId,restored.currentMapId());capture(next,"seo-restart");}
 @Test public void eachOriginalRoomRendersWithoutRebuildingFloorAndHasAnExit()throws Exception{GameView v=new GameView(c);v.layout(0,0,960,540);for(TownInteriorDef d:TownInteriorDef.TEMPLE){TownInteriorTest.enter(v,d);capture(v,d.title);TempleOriginalRenderer renderer=TownInteriorTest.field(v,"templeRenderer");int builds=renderer.floorBuilds();capture(v,d.title+"-again");assertEquals(builds,renderer.floorBuilds());assertTrue(renderer.floorBytes()<=8652800);TownInteriorTest.call(v,"leaveReagentShop");}}
 @Test public void abortedAtomicMutationRestoresBothExpenseResourcesAndAdvancement()throws Exception{GameView v=new GameView(c);RuntimeState s=TownInteriorTest.field(v,"state");RpgProgressionState r=s.rpg();r.restoreProgression(99,500_000_000);assertTrue(r.restoreJobCode("WARRIOR"));r.restoreBaseResources(17000,5000);long earned=CampaignProgress.earnedExp(r);assertFalse(F5mSaveStore.transactActive(r,null,()->{assertEquals(TempleGrowthPolicy.Result.OK,r.advanceAtTemple());assertEquals(TempleGrowthPolicy.Result.OK,r.buyTempleResource(TempleGrowthPolicy.Resource.HP,1));return false;}));assertFalse(r.firstAdvanced());assertEquals(17000,r.baseMaxHp());assertEquals(500_000_000L,r.normalExp().longValue());assertEquals(earned,CampaignProgress.earnedExp(r));assertEquals(TempleGrowthPolicy.Result.OK,r.buyTempleResource(TempleGrowthPolicy.Resource.HP,1));assertEquals(earned,CampaignProgress.earnedExp(r));}
 @Test public void realMillesPortalGuideAndOriginalStairReachSeoAndReturn()throws Exception{
  GameView v=new GameView(c);v.layout(0,0,960,540);RuntimeState s=TownInteriorTest.field(v,"state");WorldRuntimeAdapter w=TownInteriorTest.field(v,"worldAdapter");
  WorldMoveTargetController.TileCenter start=null;for(WorldMoveTargetController.TileCenter t:w.navigationTiles()){float d=(float)Math.hypot(t.x-TempleEntranceRenderer.X,t.y-TempleEntranceRenderer.Y);if(d>180&&d<245&&w.canPlayerOccupy(t.x,t.y)){start=t;break;}}assertNotNull(start);s.player().x=start.x;s.player().y=start.y;w.snapCameraToPlayer();capture(v,"milles-entrance");w.requestGroundWorld(TempleEntranceRenderer.X,TempleEntranceRenderer.Y);TownInteriorTest.tick(v,300);assertEquals("milles_interior_temple_lobby",s.currentMapId());
  TownInteriorDef lobby=TownInteriorDef.forMap(s.currentMapId());WorldRuntimeAdapter a=TownInteriorTest.field(v,"reagentShopAdapter");WorldCameraTransform.Point q=a.worldToScreen(lobby.npcX(),lobby.npcY());TownInteriorTest.tap(v,q.x,q.y-24);TownInteriorTest.tick(v,150);assertEquals("milles_interior_temple_hub",s.currentMapId());
  TownInteriorDef hub=TownInteriorDef.forMap(s.currentMapId());a=TownInteriorTest.field(v,"reagentShopAdapter");a.requestGroundWorld(hub.npcX(),hub.npcY());TownInteriorTest.tick(v,150);assertEquals("milles_interior_temple_seo",s.currentMapId());
  for(String expected:new String[]{"milles_interior_temple_hub","milles_interior_temple_lobby",WorldDef.ID}){TownInteriorDef room=TownInteriorDef.forMap(s.currentMapId());a=TownInteriorTest.field(v,"reagentShopAdapter");a.requestGroundWorld(room.exitX(),room.exitY());TownInteriorTest.tick(v,180);assertEquals(expected,s.currentMapId());}
  TownInteriorTest.tick(v,30);assertEquals(WorldDef.ID,s.currentMapId());capture(v,"milles-return");
 }

}
